const AUTHORED_ID = /\s*\{#([^\s}]+)\}\s*$/;

function slugBase(value: string): string {
  return value.toLowerCase().replace(SLUG_STRIP, '').replace(/ /g, '-');
}

/** Tracks duplicate slugs with `-1`, `-2`, … suffixes (github-slugger `BananaSlug`). */
export class HeadingIdSlugger {
  private occurrences: Record<string, number> = Object.create(null) as Record<string, number>;

  reset(): void {
    this.occurrences = Object.create(null) as Record<string, number>;
  }

  slug(value: string): string {
    const base = slugBase(value);
    let result = base;
    const original = result;
    while (Object.prototype.hasOwnProperty.call(this.occurrences, result)) {
      this.occurrences[original] = (this.occurrences[original] ?? 0) + 1;
      result = `${original}-${this.occurrences[original]}`;
    }
    this.occurrences[result] = 0;
    return result;
  }
}

function visibleText(nodes: readonly Inline[]): string {
  const parts: string[] = [];
  const walk = (list: readonly Inline[]): void => {
    for (const node of list) {
      switch (node.type) {
        case 'text':
        case 'code':
          parts.push(node.value);
          break;
        case 'emphasis':
        case 'strong':
        case 'strikethrough':
        case 'link':
          walk(node.children);
          break;
        case 'softBreak':
        case 'hardBreak':
          parts.push(' ');
          break;
        default:
          break;
      }
    }
  };
  walk(nodes);
  return parts.join('').replace(/\s+/g, ' ').trim();
}

/** Pandoc/GitHub `{#id}` suffix on the heading's visible text, if present. */
export function authoredHeadingId(nodes: readonly Inline[]): string | undefined {
  const text = visibleText(nodes);
  const match = AUTHORED_ID.exec(text);
  return match?.[1];
}

function headingLabel(nodes: readonly Inline[]): string {
  const text = visibleText(nodes);
  return text.replace(AUTHORED_ID, '').trim();
}

function headingsInOrder(node: Node, out: Heading[]): void {
  if (node.type === 'heading') out.push(node);
  for (const child of node.children ?? []) headingsInOrder(child, out);
}

/** Assigns a document-unique `id` to every heading in tree order. */
export function headingIdsForDocument(document: Document): Map<string, string> {
  const slugger = new HeadingIdSlugger();
  const ids = new Map<string, string>();
  const headings: Heading[] = [];
  for (const block of document.children) headingsInOrder(block, headings);
  for (const heading of headings) {
    const authored = authoredHeadingId(heading.children);
    const id = authored ?? slugger.slug(headingLabel(heading.children));
    ids.set(`${heading.src.start}-${heading.src.end}`, id);
  }
  return ids;
}
